/** RpcLatencyBuckets schema */
export interface RpcLatencyBuckets {
  /** Count of live RPC workers with an average latency of 100 milliseconds or more. */
  over_100ms: number;
  /** Count of live RPC workers with an average latency between 25 and 100 milliseconds. */
  under_100ms: number;
  /** Count of live RPC workers with an average latency between 5 and 25 milliseconds. */
  under_25ms: number;
  /** Count of live RPC workers with an average latency under 5 milliseconds. */
  under_5ms: number;
}

/** Point-in-time live in-memory RPC state for a single operation on the current broker process. Worker registrations and pending requests are ephemeral, reset on disconnect cleanup or broker restart, and do not represent durable backlog or recovery state. */
export interface RpcOperationDetail {
  area: string;
  diagnostics: DiagnosticSnapshot;
  operation: string;
  realm: string;
  /** Live in-memory pending requests waiting for a worker on this broker process. Not durable across disconnect or restart. */
  requests_pending: number;
  resource: string;
  /** Slowest average latency observed among live workers for this exact RPC operation on the current broker process. */
  slowest_worker_average_latency_ms: number;
  worker_latency_buckets: RpcLatencyBuckets;
  /** Live in-memory workers currently registered for this exact operation on this broker process. */
  workers_registered: number;
}

/** RpcPendingList schema */
export interface RpcPendingList {
  requests: Array<RpcPendingRequest>;
}

/** Live in-memory pending RPC request tracked by the current broker process only. Pending requests disappear on timeout, cleanup, or broker restart. */
export interface RpcPendingRequest {
  /** Approximate wall-clock age of the current in-memory pending request. */
  age_seconds?: number;
  /** Correlation identifier for the live in-memory request. */
  correlation_id?: string;
  /** Exact RPC operation route for the currently pending request. */
  route?: string;
  /** Timestamp when the current broker process accepted and tracked the request in memory. */
  submitted_at?: string;
  /** Broker-local worker session currently assigned to the pending request when one is known. */
  worker_session_id?: string | null;
}

/** RpcStats schema */
export interface RpcStats {
  acks_rejected_wrong_worker_total: number;
  backpressure_rejects_total: number;
  diagnostics: DiagnosticSnapshot;
  duplicate_correlation_rejects_total: number;
  failure_total: number;
  oldest_pending_request_age_seconds: number;
  operations_per_second: number;
  pending_routes_active: number;
  request_timeouts_total: number;
  requests_pending: number;
  requests_total: number;
  responses_dropped_closed_caller_total: number;
  responses_missing_pending_total: number;
  /** Slowest average latency observed across live RPC worker registrations on the current broker process. */
  slowest_worker_average_latency_ms: number;
  success_total: number;
  worker_latency_buckets: RpcLatencyBuckets;
  workers_registered: number;
  wrong_worker_rejects_total: number;
}

/** Live in-memory RPC worker registration for the current broker process. Workers must re-register after disconnect or broker restart. */
export interface RpcWorker {
  /** Average end-to-end latency for terminal RPC requests completed by this live worker registration in the current broker process. */
  average_latency_ms?: number;
  /** Realm extracted from the registered RPC route. */
  realm?: string;
  /** Timestamp when this live worker registration was created. Resets after disconnect or broker restart. */
  registered_at?: string;
  /** Number of terminal RPC requests completed by this live worker registration in the current broker process. */
  requests_handled?: number;
  /** Exact RPC operation route currently handled by this live worker registration. */
  route?: string;
  /** Broker-local worker session identifier for the active registration. */
  session_id?: string;
}

/** RpcWorkersList schema */
export interface RpcWorkersList {
  workers: Array<RpcWorker>;
}

/** Durable, boot-loaded schedule definition detail for the current broker. This describes persisted timing intent, not durable subscriber delivery or durable execution history. `executions_total` remains a non-authoritative placeholder until durable execution history exists. */
export interface ScheduleResourceDetail {
  area: string;
  cron?: string | null;
  diagnostics: DiagnosticSnapshot;
  enabled: boolean;
  /** Non-authoritative current broker counter. This is not durable execution history. */
  executions_total: number;
  next_run?: string | null;
  realm: string;
  resource: string;
}

/** ScheduleStats schema */
export interface ScheduleStats {
  ack_failures_total: number;
  diagnostics: DiagnosticSnapshot;
  executions_per_minute: number;
  notify_failures_total: number;
  /** Age in seconds of the oldest pending schedule fire claim in the current broker process. */
  oldest_pending_claim_age_seconds: number;
  overdue_normalizations_total: number;
  /** Count of pending schedule live handoffs currently waiting for durable acknowledgement retry. */
  pending_ack_retries: number;
  /** Total failed pending schedule claim cleanup attempts. */
  pending_claim_cleanup_failures_total: number;
  /** Total stale pending schedule claims cleaned up by this broker process. */
  pending_claims_expired_total: number;
  /** Count of durably claimed schedule occurrences that have not yet completed their live handoff acknowledgement. */
  pending_fire_claims: number;
  schedules_active: number;
  subscriptions_active: number;
}

